//! Actual SELECT construction preserves native option ownership and nearby App state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.attr(n,"id")==Some(id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn range_fragment_passive_content_actual_app_trusted_noscript_svg_paint_and_mutation(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-range-fragment-passive-content-{}.html",std::process::id())));
 std::fs::write(&file.0,r##"<!doctype html><html><head><style>body{margin:0;background:white}#paint{position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#menu{position:absolute;left:20px;top:80px;width:150px;height:30px}#newmenu{position:absolute;left:20px;top:130px;width:150px;height:30px}#mount{position:absolute;left:20px;top:180px;width:80px;height:80px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style></head><body><div id=paint>Indicator</div><div id=mount></div><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Construct select</button><div id=destination></div><script>
var mount=document.getElementById('mount'),watch=new MutationObserver(function(){}),round=0,host,svg,rect,raw='<style>#paint{background:#ff00ff}</style><img id=fake src=missing><scr'+'ipt>window.bad=1;</scr'+'ipt>&amp;';watch.observe(mount,{childList:true});document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'actual pointer';if(round===0){var r=document.createRange();r.selectNodeContents(mount);var fragment=r.createContextualFragment('<noscript id=passive style="display:none">'+raw+'</noscript><svg id=vector xmlns="http://www.w3.org/2000/svg" width=80 height=80 viewBox="0 0 20 20"><rect id=shape width=20 height=20 fill="#e03040"/></svg>');host=fragment.firstChild;svg=fragment.lastChild;rect=svg.firstChild;if(fragment.childNodes.length!==2||host.firstChild.nodeType!==3||host.textContent!==raw||svg.namespaceURI!=='http://www.w3.org/2000/svg'||rect.namespaceURI!=='http://www.w3.org/2000/svg'||host.ownerDocument!==document||rect.ownerDocument!==document||host.isConnected||svg.isConnected||document.getElementById('vector')!==null||watch.takeRecords().length)throw 'actual passive detached payload';mount.appendChild(fragment);var records=watch.takeRecords();if(fragment.firstChild!==null||mount.firstChild!==host||mount.lastChild!==svg||document.getElementById('shape')!==rect||records.length!==1||records[0].addedNodes.length!==2||records[0].addedNodes[0]!==host||records[0].addedNodes[1]!==svg)throw 'genuine mixed fragment draining';}else{rect.setAttribute('fill','#40a020');host.firstChild.appendData('\udfff\ud800');if(host.textContent!==raw+'\udfff\ud800'||host.childNodes.length!==1||svg.firstChild!==rect)throw 'native passive mutation';}if(document.getElementById('fake')!==null||document.querySelectorAll('script').length!==1||window.bad!==undefined||document.getElementById('neighbor').value!=='edited neighbor')throw 'literal fallback and native neighbor';document.getElementById('paint').className='ready';document.title='Range passive '+round;round++;};
</script></body></html>"##).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let before=app.draw();assert_eq!(before.pixels[(app.content_top()+40)as usize*before.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..2 {let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);
 assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Range passive {round}"));let svg=node(&app,"vector");let shape=node(&app,"shape");let host=node(&app,"passive");assert_eq!(app.document.nodes[svg].namespace,crate::html::Namespace::Svg);assert_eq!(app.document.nodes[shape].namespace,crate::html::Namespace::Svg);assert_eq!(app.document.nodes[host].children.len(),1);
 let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+200)as usize*painted.width+40],[0xe03040,0x40a020][round]);assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],0x228844);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}
